using NUnit.Framework;
using Seqeron.Mcp.Analysis.Tools;

namespace Seqeron.Mcp.Analysis.Tests;

// <auto-generated by scripts/docs/gen_emboss_wp63_tools.py: do not edit> B09 WP63 (F282): the MCP tools of the EMBOSS programs; the expected text is what the installed EMBOSS 6.6.0 program writes for the example of the tool document.
[TestFixture]
public class EmbossProgramTools3Tests
{
    // the programs print the date of the run: the tools take it from the clock, so the date lines are compared as a placeholder
    private static string Norm(string s) => System.Text.RegularExpressions.Regex.Replace(System.Text.RegularExpressions.Regex.Replace(s, "# Rundate: .*", "# Rundate: X"), "(#!Date |##date )\\d{4}-\\d{2}-\\d{2}", "$1X");

    [Test]
    public void Tcode_WritesWhatTheInstalledProgramWrites()
    {
        var r = AnalysisTools.Tcode(">s1 test\\n", window: 200, step: 30);
        Assert.That(Norm(r.Text), Is.EqualTo("########################################\n# Program: tcode\n# Rundate: X\n# Commandline: tcode\n#    -auto\n#    -sequence sequence.dat\n#    -window 200\n#    -step 30\n#    -outfile out.txt\n# Report_format: table\n# Report_file: out.txt\n########################################\n\n#=======================================\n#\n# Sequence: s1     from: 1   to: 312\n# HitCount: 4\n#\n# Fickett TESTCODE statistic\n#\n#=======================================\n\n  Start     End  Strand   Score Estimation\n      1     200       +   1.048 Coding    \n     31     230       +   1.034 Coding    \n     61     260       +   1.087 Coding    \n     91     290       +   1.046 Coding    \n\n#---------------------------------------\n#---------------------------------------\n\n#---------------------------------------\n# Total_sequences: 1\n# Total_length: 312\n# Reported_sequences: 1\n# Reported_hitcount: 4\n#---------------------------------------\n"));
    }

    [Test]
    public void Checktrans_WritesWhatTheInstalledProgramWrites()
    {
        var r = AnalysisTools.Checktrans(">p1 test\nMKVLAAGIV*ACDEFGHIK*PQRS\n", orfml: 3);
        Assert.That(Norm(r.Text), Is.EqualTo("\n\nCHECKTRANS of p1 from 1 to 25\n\n\tORF#\tPos\tLen\tORF Range\tSequence name\n\n\t1\t10\t9\t1-9\tp1_1\n\t2\t20\t9\t11-19\tp1_2\n\t3\t25\t4\t21-24\tp1_3\n\n\tTotal STOPS:     2\n\n "));
        Assert.That(Norm(r.Files["features.txt"]), Is.EqualTo("##gff-version 3\n##sequence-region p1 1 24\n#!Date X\n#!Type Protein\n#!Source-version EMBOSS 6.6.0.0\np1\tchecktrans\tpolypeptide_region\t1\t9\t.\t.\t.\tID=p1.1\np1\tchecktrans\tpolypeptide_region\t11\t19\t.\t.\t.\tID=p1.2\np1\tchecktrans\tpolypeptide_region\t21\t24\t.\t.\t.\tID=p1.3\n"));
        Assert.That(Norm(r.Files["seqout.txt"]), Is.EqualTo(">p1_1\nMKVLAAGIV\n>p1_2\nACDEFGHIK\n>p1_3\nPQRS\n"));
    }

    [Test]
    public void Wordfinder_WritesWhatTheInstalledProgramWrites()
    {
        var r = AnalysisTools.Wordfinder(">q1\nACGTACGTACGGGTTTTAAACCCGGGATATATCGCGCGTAGCTAGCTAGCTAGGGGATCCC\n", targetSequence: ">t1\nGGGACGTACGTACGGGTTTTAAACCCGGGATATATCGCGCGTAGCTAGCTAGCTAGGGGATCCCAAAAAA\n");
        Assert.That(Norm(r.Text), Is.EqualTo("########################################\n# Program: wordfinder\n# Rundate: X\n# Commandline: wordfinder\n#    -auto\n#    -asequence asequence.dat\n#    -bsequence bsequence.dat\n#    -outfile out.txt\n#    -errfile err.txt\n# Align_format: simple\n# Report_file: out.txt\n########################################\n\n#=======================================\n#\n# Aligned_sequences: 2\n# 1: q1\n# 2: t1\n# Matrix: EDNAFULL\n# Gap_penalty: 30.0\n# Extend_penalty: 1.5\n#\n# Length: 61\n# Identity:      61/61 (100.0%)\n# Similarity:    61/61 (100.0%)\n# Gaps:           0/61 ( 0.0%)\n# Score: 305.0\n# \n# Wordscore:61\n# Alignlength:61\n#\n#=======================================\n\nq1                 1 ACGTACGTACGGGTTTTAAACCCGGGATATATCGCGCGTAGCTAGCTAGC     50\n                     ||||||||||||||||||||||||||||||||||||||||||||||||||\nt1                 4 ACGTACGTACGGGTTTTAAACCCGGGATATATCGCGCGTAGCTAGCTAGC     53\n\nq1                51 TAGGGGATCCC     61\n                     |||||||||||\nt1                54 TAGGGGATCCC     64\n\n\n#---------------------------------------\n#---------------------------------------\n"));
        Assert.That(Norm(r.Files["err.txt"]), Is.EqualTo("Target 1 t1 matches 1\n"));
    }

    [Test]
    public void Marscan_WritesWhatTheInstalledProgramWrites()
    {
        var r = AnalysisTools.Marscan(">s1 test\nCCCCCCCCCCAATAACAACCCCCCCCCCCCCCAATGTAAGGTTGCCCCTTTTTTTTTT\n");
        Assert.That(Norm(r.Text), Is.EqualTo("##gff-version 3\n##sequence-region s1 1 48\n#!Date X\n#!Type DNA\n#!Source-version EMBOSS 6.6.0.0\ns1\tmarscan\tregulatory_region\t11\t48\t.\t+\t.\tID=s1.1;note=*type MAR/SAR recognition site (MRS);note=*start8bp 11;note=*end8bp 18;note=*start16bp 33;note=*end16bp 48\n"));
    }

