        Assert.That(Norm(r.Files["plotorf5.dat"]), Is.EqualTo("##Multi 2D Plot Small\n##Title Potential codons (rectangles)\n##Graphs 6\n##Number 5\n##Points 0\n##XminA 1.000000 XmaxA 68.000000 YminA 0.000000 YmaxA 1.000000\n##Xmin 1.000000 Xmax 68.000000 Ymin 0.000000 Ymax 1.000000\n##ScaleXmin 1.000000 ScaleXmax 68.000000 ScaleYmin 0.000000 ScaleYmax 1.000000\n##Maintitle R2\n##Subtitle \n##Xtitle Sequence\n##Ytitle Orf\n##DataObjects\n##Number 1\nFilled Rectangle x1 1.000000 y1 0.000000 x2 52.000000 y2 1.000000 colour 4\n##GraphObjects\n##Number 0\n"));
        Assert.That(Norm(r.Files["plotorf6.dat"]), Is.EqualTo("##Multi 2D Plot Small\n##Title Potential codons (rectangles)\n##Graphs 6\n##Number 6\n##Points 0\n##XminA 1.000000 XmaxA 68.000000 YminA 0.000000 YmaxA 1.000000\n##Xmin 1.000000 Xmax 68.000000 Ymin 0.000000 Ymax 1.000000\n##ScaleXmin 1.000000 ScaleXmax 68.000000 ScaleYmin 0.000000 ScaleYmax 1.000000\n##Maintitle R3\n##Subtitle \n##Xtitle Sequence\n##Ytitle Orf\n##DataObjects\n##Number 0\n##GraphObjects\n##Number 0\n"));
