    [Test]
    public void Tools_RefuseAnEmptySequenceAndABadValueWithTheMessagesOfTheLibrary()
    {
        Assert.Throws<ArgumentException>(() => AnalysisTools.Tcode(""));
        var e = Assert.Throws<ArgumentException>(() => AnalysisTools.Plotorf(">o1\nATGAAATAG\n", graph: "bogus"));
        Assert.That(e!.Message, Does.Contain("Invalid XY graph value 'bogus'"));
        var f = Assert.Throws<ArgumentException>(() => AnalysisTools.Tcode(">s1\n" + new string('A', 300) + "\n", plot: true, graph: "png"));
        Assert.That(f!.Message, Does.Contain("plplot"));
    }
}
